@PactConsumerTest
@PactTestFor(providerName = "ArticlesProvider")
class ArticleClientPactTest {
  @Pact(consumer = "article-consumer", provider = "ArticlesProvider")
  RequestResponsePact pact(PactDslWithProvider builder) {
    return builder.given("articles exist")
        .uponReceiving("a request for articles").path("/articles.json").method("GET")
        .willRespondWith().status(200)
          .body(new PactDslJsonBody().minArrayLike("articles").id().stringType("title").closeObject().closeArray())
        .toPact();
  }
  @Test
  void returnsArticles(MockServer server) { /* new ArticleClient(server.getUrl()) */ }
}

